WITH _hq_raw AS (SELECT "created_at" AS _hq_row_1, "amount_cents" AS _hq_row_2, NULL AS _hq_row_3 FROM "analytics"."orders" WHERE "tenant_id" = $1 AND "created_at" >= (CASE WHEN pg_typeof((SELECT "created_at" FROM "analytics"."orders" LIMIT 0)) = 'date'::regtype THEN CAST($2 AS timestamp) AT TIME ZONE 'UTC' ELSE CAST($2 AS timestamp) AT TIME ZONE 'UTC' END) AND "created_at" < (CASE WHEN pg_typeof((SELECT "created_at" FROM "analytics"."orders" LIMIT 0)) = 'date'::regtype THEN CAST($3 AS timestamp) AT TIME ZONE 'UTC' ELSE CAST($3 AS timestamp) AT TIME ZONE 'UTC' END)),
_hq_source AS (SELECT (CASE WHEN pg_typeof(_hq_row_1) = 'date'::regtype THEN (_hq_row_1)::timestamp AT TIME ZONE 'America/New_York' ELSE (_hq_row_1)::timestamptz END) AS _hq_time, _hq_row_2 AS _hq_v0, _hq_row_3 AS _hq_a0 FROM _hq_raw WHERE (_hq_row_1 IS NOT NULL)),
_hq_bounds AS (SELECT * FROM (SELECT (CASE WHEN CAST($4 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($4 AS text) AS timestamptz) ELSE CAST(CAST($4 AS text) AS timestamp) AT TIME ZONE 'America/New_York' END) AS _hq_lower) AS _hq_step0 CROSS JOIN LATERAL (SELECT (CASE WHEN CAST($5 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($5 AS text) AS timestamptz) ELSE CAST(CAST($5 AS text) AS timestamp) AT TIME ZONE 'America/New_York' END) AS _hq_upper) AS _hq_step1 CROSS JOIN LATERAL (SELECT date_trunc('hour', _hq_lower, 'America/New_York') AS _hq_first) AS _hq_step2 CROSS JOIN LATERAL (SELECT date_trunc('hour', _hq_upper, 'America/New_York') AS _hq_last) AS _hq_step3),
_hq_series AS (SELECT ((_hq_first) + (generate_series(0, (((EXTRACT(EPOCH FROM date_trunc('hour', _hq_last, 'America/New_York')) - EXTRACT(EPOCH FROM date_trunc('hour', _hq_first, 'America/New_York'))) / 3600)::bigint + 1 + 0 + CAST(CASE WHEN (pg_typeof((SELECT _hq_row_1 FROM _hq_raw LIMIT 0)) = 'date'::regtype) THEN '[hypequery] Sub-day time measures require a time-of-day column; Date and Date32 are not supported.' ELSE '0' END AS integer) + 0 + 0 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 hour') AS _hq_period FROM _hq_bounds),
_hq_shift_ranges0 AS (SELECT _hq_period, ((GREATEST(_hq_period, _hq_lower)) - (1) * INTERVAL '1 hour') AS _hq_shift_lower, ((LEAST(((_hq_period) + (1) * INTERVAL '1 hour'), _hq_upper)) - (1) * INTERVAL '1 hour') AS _hq_shift_upper, (_hq_period > _hq_lower OR TRUE) AS _hq_shift_lower_inclusive, (_hq_upper < ((_hq_period) + (1) * INTERVAL '1 hour') AND TRUE) AS _hq_shift_upper_inclusive FROM _hq_series CROSS JOIN _hq_bounds),
_hq_shift_keys0 AS (SELECT *, ((date_trunc('hour', _hq_shift_lower, 'America/New_York')) + (generate_series(0, (GREATEST(0, ((EXTRACT(EPOCH FROM date_trunc('hour', date_trunc('hour', _hq_shift_upper, 'America/New_York'), 'America/New_York')) - EXTRACT(EPOCH FROM date_trunc('hour', date_trunc('hour', _hq_shift_lower, 'America/New_York'), 'America/New_York'))) / 3600)::bigint + CASE WHEN _hq_shift_upper > date_trunc('hour', _hq_shift_upper, 'America/New_York') OR _hq_shift_upper_inclusive THEN 1 ELSE 0 END)) - 1)) * INTERVAL '1 hour') AS _hq_source_period FROM _hq_shift_ranges0),
_hq_shift_ranges1 AS (SELECT _hq_period, ((((((GREATEST(_hq_period, _hq_lower) AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York') + (((((((_hq_period AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York'))::date - (((((GREATEST(_hq_period, _hq_lower) AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York'))::date)::bigint + (((GREATEST(_hq_period, _hq_lower) AT TIME ZONE 'America/New_York'))::date - ((_hq_period AT TIME ZONE 'America/New_York'))::date)::bigint) * INTERVAL '1 day') AT TIME ZONE 'America/New_York') AS _hq_shift_lower, CASE WHEN _hq_upper >= ((_hq_period) + (1) * INTERVAL '1 hour') THEN (((((_hq_period AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York')) + (1) * INTERVAL '1 hour') ELSE ((((((LEAST(((_hq_period) + (1) * INTERVAL '1 hour'), _hq_upper) AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York') + (((((((_hq_period AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York'))::date - (((((LEAST(((_hq_period) + (1) * INTERVAL '1 hour'), _hq_upper) AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York'))::date)::bigint + (((LEAST(((_hq_period) + (1) * INTERVAL '1 hour'), _hq_upper) AT TIME ZONE 'America/New_York'))::date - ((_hq_period AT TIME ZONE 'America/New_York'))::date)::bigint) * INTERVAL '1 day') AT TIME ZONE 'America/New_York') END AS _hq_shift_upper, (_hq_period > _hq_lower OR TRUE) AS _hq_shift_lower_inclusive, (_hq_upper < ((_hq_period) + (1) * INTERVAL '1 hour') AND TRUE) AS _hq_shift_upper_inclusive FROM _hq_series CROSS JOIN _hq_bounds),
_hq_shift_keys1 AS (SELECT *, ((date_trunc('hour', _hq_shift_lower, 'America/New_York')) + (generate_series(0, (GREATEST(0, ((EXTRACT(EPOCH FROM date_trunc('hour', date_trunc('hour', _hq_shift_upper, 'America/New_York'), 'America/New_York')) - EXTRACT(EPOCH FROM date_trunc('hour', date_trunc('hour', _hq_shift_lower, 'America/New_York'), 'America/New_York'))) / 3600)::bigint + CASE WHEN _hq_shift_upper > date_trunc('hour', _hq_shift_upper, 'America/New_York') OR _hq_shift_upper_inclusive THEN 1 ELSE 0 END)) - 1)) * INTERVAL '1 hour') AS _hq_source_period FROM _hq_shift_ranges1),
_hq_scanned AS (SELECT * FROM _hq_source CROSS JOIN _hq_bounds WHERE (_hq_time IN (SELECT r._hq_time FROM _hq_source AS r INNER JOIN _hq_shift_keys0 AS b ON date_trunc('hour', r._hq_time, 'America/New_York') = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper)))) OR (_hq_time IN (SELECT r._hq_time FROM _hq_source AS r INNER JOIN _hq_shift_keys1 AS b ON date_trunc('hour', r._hq_time, 'America/New_York') = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper))))),
_hq_skeleton AS (SELECT * FROM _hq_series),
_hq_fan0 AS (SELECT r.*, b._hq_period FROM _hq_scanned AS r INNER JOIN _hq_shift_keys0 AS b ON date_trunc('hour', r._hq_time, 'America/New_York') = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper))),
_hq_agg0 AS (SELECT _hq_period, SUM(_hq_v0) AS _hq_m0 FROM _hq_fan0 GROUP BY _hq_period),
_hq_fan1 AS (SELECT r.*, b._hq_period FROM _hq_scanned AS r INNER JOIN _hq_shift_keys1 AS b ON date_trunc('hour', r._hq_time, 'America/New_York') = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper))),
_hq_agg1 AS (SELECT _hq_period, SUM(_hq_v0) AS _hq_m1 FROM _hq_fan1 GROUP BY _hq_period),
_hq_values AS (SELECT (s._hq_period AT TIME ZONE 'America/New_York') AS period, m0._hq_m0 AS "priorHour", m1._hq_m1 AS "priorMonth" FROM _hq_skeleton AS s LEFT JOIN _hq_agg0 AS m0 ON s._hq_period = m0._hq_period LEFT JOIN _hq_agg1 AS m1 ON s._hq_period = m1._hq_period),
_hq_result AS (SELECT "period", "priorHour", "priorMonth" FROM _hq_values UNION ALL SELECT NULL AS "period", NULL AS "priorHour", NULL AS "priorMonth" FROM _hq_bounds WHERE 0 + CAST(CASE WHEN (pg_typeof((SELECT _hq_row_1 FROM _hq_raw LIMIT 0)) = 'date'::regtype) THEN '[hypequery] Sub-day time measures require a time-of-day column; Date and Date32 are not supported.' ELSE '0' END AS integer) + 0 + 0 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer) + 0 + (SELECT CAST(CASE WHEN COUNT(*) FILTER (WHERE (FLOOR(EXTRACT(HOUR FROM (_hq_period AT TIME ZONE 'America/New_York')))::int != FLOOR(EXTRACT(HOUR FROM ((((_hq_period AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York')))::int OR FLOOR(EXTRACT(MINUTE FROM (_hq_period AT TIME ZONE 'America/New_York')))::int != FLOOR(EXTRACT(MINUTE FROM ((((_hq_period AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York')))::int OR FLOOR(EXTRACT(SECOND FROM (_hq_period AT TIME ZONE 'America/New_York')))::int != FLOOR(EXTRACT(SECOND FROM ((((_hq_period AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York')))::int) OR (FLOOR(EXTRACT(HOUR FROM (GREATEST(_hq_period, _hq_lower) AT TIME ZONE 'America/New_York')))::int != FLOOR(EXTRACT(HOUR FROM ((((GREATEST(_hq_period, _hq_lower) AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York')))::int OR FLOOR(EXTRACT(MINUTE FROM (GREATEST(_hq_period, _hq_lower) AT TIME ZONE 'America/New_York')))::int != FLOOR(EXTRACT(MINUTE FROM ((((GREATEST(_hq_period, _hq_lower) AT TIME ZONE 'America/New_York') - (1) * INTERVAL '1 month') AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York')))::int OR FLOOR(EXTRACT(SECOND FROM (G